"use client";

// DentitionSnapshot — a front-view render of the full 3D dentition that is
// captured to a PNG once the models have loaded, then shown as an <img>. The
// image prints reliably (a live WebGL canvas does not) and frees its GL context
// after capture, so it's safe to use in the Rx preview/print and inside the
// exam without exhausting the browser's WebGL context budget.

import { Suspense, useEffect, useMemo, useRef, useState } from "react";
import { Canvas, useThree } from "@react-three/fiber";
import DentitionView from "./DentitionView";

const EXAM_CHART_PREFIX = "dental.exam.chart.";

function normalizeChart(raw) {
  if (!raw) return null;
  const toothDiagnoses = {};
  Object.entries(raw.toothDiagnoses || {}).forEach(([fdi, v]) => {
    toothDiagnoses[fdi] = v instanceof Set ? v : new Set(Array.isArray(v) ? v : []);
  });
  const implantTeeth = new Set();
  if (raw.implantTeeth) (raw.implantTeeth instanceof Set ? [...raw.implantTeeth] : (Array.isArray(raw.implantTeeth) ? raw.implantTeeth : [])).forEach((f) => implantTeeth.add(f));
  Object.entries(toothDiagnoses).forEach(([fdi, set]) => { if (set.has("Implant")) implantTeeth.add(fdi); });
  const findingsByTooth = {};
  Object.entries(raw.findingsByTooth || {}).forEach(([fdi, list]) => { findingsByTooth[fdi] = Array.isArray(list) ? list : []; });
  const hasData =
    Object.values(toothDiagnoses).some((s) => s.size > 0) ||
    implantTeeth.size > 0 ||
    Object.values(findingsByTooth).some((a) => a.length > 0);
  return hasData ? { toothDiagnoses, findingsByTooth, implantTeeth } : null;
}

function FrontCamera() {
  const { camera } = useThree();
  useEffect(() => {
    camera.position.set(0, 2.5, 16.5);
    camera.lookAt(0, -0.9, -0.3);
    camera.updateProjectionMatrix();
  }, [camera]);
  return null;
}

// Mounted inside the Suspense boundary, so it only runs after the tooth models
// have resolved. Renders one frame and grabs the canvas as a PNG.
function CaptureWhenReady({ onCapture }) {
  const { gl, scene, camera } = useThree();
  const grabbed = useRef(false);
  useEffect(() => {
    const t = setTimeout(() => {
      if (grabbed.current) return;
      try {
        gl.render(scene, camera);
        const url = gl.domElement.toDataURL("image/png");
        if (url && url.length > 5000) { grabbed.current = true; onCapture(url); }
      } catch { /* tainted/unsupported — leave the live canvas */ }
    }, 900);
    return () => clearTimeout(t);
  }, [gl, scene, camera, onCapture]);
  return null;
}

export function DentitionSnapshot({ patientId, chart: chartProp, toothDiagnoses, findingsByTooth, implantTeeth, patientType = "adult", height = 190, title = "Dental Chart" }) {
  const [img, setImg] = useState(null);
  const chart = useMemo(() => {
    if (toothDiagnoses) return normalizeChart({ toothDiagnoses, findingsByTooth, implantTeeth });
    if (chartProp) return normalizeChart(chartProp);
    if (typeof window !== "undefined") {
      try { const raw = window.localStorage.getItem(`${EXAM_CHART_PREFIX}${patientId || "apt-1"}`); return normalizeChart(raw ? JSON.parse(raw) : null); } catch { return null; }
    }
    return null;
  }, [toothDiagnoses, findingsByTooth, implantTeeth, chartProp, patientId]);

  // Re-capture when the underlying data changes.
  const sig = useMemo(() => {
    if (!chart) return "";
    const d = Object.entries(chart.toothDiagnoses).map(([f, s]) => `${f}:${[...s].sort().join("+")}`).sort().join("|");
    const fnd = Object.entries(chart.findingsByTooth).map(([f, l]) => `${f}:${l.length}`).sort().join("|");
    return `${d}__${fnd}__${[...chart.implantTeeth].sort().join(",")}`;
  }, [chart]);
  useEffect(() => { setImg(null); }, [sig]);

  if (!chart) return null;

  return (
    <section style={{ marginTop: 10, breakInside: "avoid", WebkitPrintColorAdjust: "exact", printColorAdjust: "exact" }} data-dentition-snapshot="true">
      {title ? (
        <h3 style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, fontWeight: 700, color: "#334155", margin: "0 0 6px", fontFamily: "Inter, sans-serif" }}>
          {title}
          <span style={{ fontSize: 9, fontWeight: 500, color: "#94a3b8" }}>(front view)</span>
        </h3>
      ) : null}
      <div style={{ position: "relative", width: "100%", height, borderRadius: 10, overflow: "hidden", background: "linear-gradient(180deg,#f8fafc,#eef2f7)", border: "1px solid #e2e8f0" }}>
        {img ? (
          <img src={img} alt="Dentition front view" style={{ width: "100%", height: "100%", objectFit: "contain" }} />
        ) : (
          <Canvas
            key={sig}
            dpr={[1, 2]}
            gl={{ preserveDrawingBuffer: true, alpha: true, antialias: true, toneMapping: 3, toneMappingExposure: 1.3 }}
            camera={{ position: [0, 2.5, 16.5], fov: 35 }}
            style={{ width: "100%", height: "100%" }}
          >
            <FrontCamera />
            <ambientLight intensity={0.8} />
            <directionalLight position={[3, 5, 4]} intensity={1.0} />
            <directionalLight position={[-2, 3, -2]} intensity={0.4} />
            <directionalLight position={[0, -2, 1]} intensity={0.3} />
            <Suspense fallback={null}>
              <DentitionView
                patientType={patientType}
                layoutMode="natural"
                disableSelection
                showTreatmentTags={false}
                toothDiagnoses={chart.toothDiagnoses}
                findingsByTooth={chart.findingsByTooth}
                implantTeeth={chart.implantTeeth}
                onSelectTooth={() => {}}
                onHoverTooth={() => {}}
                externalHoveredFdi={null}
                allEntries={[]}
                toothNotes={{}}
                agentPulseFdis={new Set()}
              />
              <CaptureWhenReady onCapture={setImg} />
            </Suspense>
          </Canvas>
        )}
      </div>
    </section>
  );
}
